queries.query:
azimuthHomed = from(bucket: "efd/autogen")
  |> range(start: -7d) // Large range to ensure the most recent record is found
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTMount.logevent_azimuthHomed" and r["_field"] == "homed")
  |> last()
  |> map(fn: (r) => ({
    azimuthHomed: if r._value == true then "HOMED" else "NOT HOMED"
    }))

elevationHomed = from(bucket: "efd/autogen")
  |> range(start: -7d) // Large range to ensure the most recent record is found
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTMount.logevent_elevationHomed" and r["_field"] == "homed")
  |> last()
  |> map(fn: (r) => ({
    elevationHomed: if r._value == true then "HOMED" else "NOT HOMED"
    }))

union(
  tables: [azimuthHomed, elevationHomed]
)
  |> reduce(
    identity: {azimuth: "NOT HOMED", elevation: "NOT HOMED"},
    fn: (r, accumulator) => ({
      azimuth: if exists r.azimuthHomed then r.azimuthHomed else accumulator.azimuth,
      elevation: if exists r.elevationHomed then r.elevationHomed else accumulator.elevation
    })
  )
  |> map(fn: (r) => ({
    status: if r.azimuth == "HOMED" and r.elevation == "HOMED" then "HOMED"
            else if r.azimuth == "HOMED" and r.elevation == "NOT HOMED" then "AZIMUTH ONLY"
            else if r.azimuth == "NOT HOMED" and r.elevation == "HOMED" then "ELEVATION ONLY"
            else "NOT HOMED"
    }))
  |> keep(columns: ["status"]) // Keep only the final status column

